WITH filtered AS (SELECT *, UPPER(TRIM(full_name)) AS full_name_normalized, CASE WHEN level IN ('L2', 'L5') THEN 'Group A' ELSE 'Other' END AS level_group, COALESCE(job_title, 'NONE') AS resolved_job_title FROM employees WHERE job_title IN ('Intern', 'Analyst', 'Engineer')) SELECT * FROM (SELECT dept_id, job_title, salary FROM filtered) src PIVOT (MAX(salary) AS amount, COUNT(1) AS cnt FOR job_title IN ('Director' AS director, 'Manager' AS manager))
